function countVowels(str) {
  // Remove spaces and punctuation marks from the string
  str = str.replace(/[^a-zA-Z]/g, '').toLowerCase();

  // Count the occurrences of each vowel (a, e, i, o, u)
  let count = { a: 0, e: 0, i: 0, o: 0, u: 0 };

  for (let I = 0; I < str.length; i++) {
    let char = str[i];
    if (char === 'a') {
      count.a++;
    } else if (char === 'e') {
      count.e++;
    } else if (char === 'i') {
      count.i++;
    } else if (char === 'o') {
      count.o++;
    } else if (char === 'u') {
      count.u++;
    }
  }

  // Return the total number of vowels
  return Object.values(count).reduce((a, b) => a + b);
}

// Test the function
