namespace RestServiceWrapper
{
    public abstract class RestServiceBase
    {
        protected string BaseUrl { get; set; }
        protected string AuthToken { get; set; }
        protected HttpClient Client { get; set; }

        public RestServiceBase(string baseUrl, string authToken)
        {
            BaseUrl = baseUrl;
            AuthToken = authToken;
            Client = new HttpClient();
            Client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", AuthToken);
        }

        protected async Task<TResponse> SendAsync<TResponse>(string uri, HttpMethod method, object requestBody = null)
        {
            var requestMessage = CreateRequestMessage(uri, method, requestBody);
            var response = await Client.SendAsync(requestMessage);
            return ParseResponse<TResponse>(response);
        }

        private static HttpRequestMessage CreateRequestMessage(string uri, HttpMethod method, object requestBody)
        {
            var requestMessage = new HttpRequestMessage(method, uri);
            if (requestBody != null)
            {
                requestMessage.Content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(requestBody), Encoding.UTF8, "application/json");
            }
            return requestMessage;
        }

        private static TResponse ParseResponse<TResponse>(HttpResponseMessage response)
        {
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to execute request: status code {response.StatusCode}");
            }
            return Newtonsoft.Json.JsonConvert.DeserializeObject<TResponse>(await response.Content.ReadAsStringAsync());
        }
    }

