    @Value("${social.provider.google.client_id}")
    private String googleClientId;

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.oauth2Login().loginPage("/login").successHandler((authentication) -> {
            // Redirect to home page after successful authentication
            return new RedirectStrategyContext() {
                @Override
                public ServletContext getApplicationContext() {
                    return request.getServletContext();
                }
            };
        }).failureUrl("/login?error=true")
            .and().exceptionHandling().authenticationEntryPoint(jwtAuthenticationEntryPoint).and().sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS);
        http.authorizeRequests()
            .antMatchers("/api/**").hasAnyRole("ADMIN", "USER")
            .antMatchers("/login/**").permitAll()
            .and().csrf().disable();
        http.addFilterBefore(jwtRequestFilter(), UsernamePasswordAuthenticationFilter.class);
    }

    @Bean
    public JwtAuthenticationFilter jwtRequestFilter() throws Exception {
        return new JwtAuthenticationFilter(authenticationManager());
    }

